      for (let x = xMin; x <= xMax; x++) {
        // barycentric in screen space
        let t1 = (x - a.x) / (b.x - a.x);
        let t2 = (y - a.y) / (b.y - a.y);
        if (b.x !== a.x || b.y !== a.y) {
          t1 = (x - a.x) / (b.x - a.x);
          t2 = (y - a.y) / (b.y - a.y);
        }
        let t3 = 1 - t1 - t2;
