function loop(now) {
  if (!paused) {
    update();
    buildTriangles();
    render();
  }
  if (now - lastTime >= 1000) {
    fps = frameCount;
    FPS.textContent = 'FPS: ' + fps;
    frameCount = 0;
    lastTime = now;
  }
  frameCount++;
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

